WITH unpacked AS (SELECT id, service, host, log_ts, level, status_code, payload_json, GET_JSON_OBJECT(payload_json, '$.user.id') AS user_id, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count FROM app_logs WHERE service IN ('checkout', 'auth')) SELECT id, service, host, log_ts, level, status_code, payload_json, user_id, retry_count, FIRST_VALUE(retry_count) IGNORE NULLS OVER (ORDER BY retry_count, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_retry_count, NTILE(5) OVER (ORDER BY retry_count DESC, id) AS retry_count_bucket, AVG(retry_count) OVER (PARTITION BY level ORDER BY log_ts, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS retry_count_avg_3_prior FROM unpacked;
